import { useState, useEffect, useCallback } from 'react';
import { RoomService } from '@/services/room.service';
import { RoomMemberService } from '@/services/room-member.service';
import { Room, RoomPayload } from '@/types/room';
import { client, DB_ID, COLLECTIONS } from '@/lib/appwrite';
import { useSession } from './useSession';

export function useRooms() {
    const { session, isAuthenticated } = useSession();
    const [rooms, setRooms] = useState<Room[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const fetchRooms = useCallback(async (searchQuery?: string) => {
        setLoading(true);
        try {
            const response = await RoomService.list(searchQuery);
            setRooms(response.documents);
        } catch (err: any) {
            console.error('Fetch rooms failed:', err);
            setError(err.message || 'Failed to fetch rooms');
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchRooms();

        const unsubscribe = client.subscribe(
            `databases.${DB_ID}.collections.${COLLECTIONS.ROOMS}.documents`,
            (response) => {
                if (response.events.includes('databases.*.collections.*.documents.*.create')) {
                    const newRoom = response.payload as Room;
                    if (newRoom.status === 'OPEN' && newRoom.isPublic) {
                        setRooms(prev => [newRoom, ...prev]);
                    }
                } else if (response.events.includes('databases.*.collections.*.documents.*.update')) {
                    const updatedRoom = response.payload as Room;
                    setRooms(prev => prev.map(r => r.$id === updatedRoom.$id ? updatedRoom : r));
                } else if (response.events.includes('databases.*.collections.*.documents.*.delete')) {
                    const deletedRoom = response.payload as Room;
                    setRooms(prev => prev.filter(r => r.$id !== deletedRoom.$id));
                }
            }
        );

        return () => {
            unsubscribe();
        };
    }, [fetchRooms]);

    const createRoom = async (payload: RoomPayload) => {
        // Rule #3: Create Room using active session
        if (!isAuthenticated || !session?.userId) {
            throw new Error("Active session required to create room");
        }

        try {
            // 1. Create Room
            const newRoom = await RoomService.create(payload);

            // 2. Add Creator as Member (Rule #3)
            await RoomMemberService.add({
                room: newRoom.$id,
                user: session.userId,
                role: 'CREATOR',
            });

            return newRoom;
        } catch (err: any) {
            console.error('Create room failed:', err);
            throw err;
        }
    };

    return {
        rooms,
        loading,
        error,
        createRoom,
        refresh: fetchRooms
    };
}
